import {useCallback, useState} from 'react'
import {FormControl, Radio, RadioGroup, ConfirmationDialog} from '@primer/react'
import {useOrganizationAccessPolicy} from '../contexts/OrganizationAccessPolicyContext'
import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import type {DefaultModel, Publisher} from '../types'
import {RulesTable} from './RulesTable'
import {allowAllOrgModelsPayload} from '../hooks/use-update-organization-access-policy'

export function ModelsPermissions({
  customKeys,
  models,
  orgDisplayLogin,
  publishers,
}: {
  customKeys: CustomKey[]
  models: Array<CustomModel | DefaultModel>
  orgDisplayLogin: string
  publishers: Publisher[]
}) {
  const {isAllowlist, isModelsEnabled, allowedModelKeys, allowedCustomModelIds, updateOrganizationAccessPolicy} =
    useOrganizationAccessPolicy()
  const anyRestrictions = useCallback(() => {
    const defaultModels = models.filter(m => 'publisherId' in m)
    const allDefaultModelKeys = new Set(defaultModels.map(model => model.key))
    const blockedDefaultModelKeys = allDefaultModelKeys.difference(allowedModelKeys)
    const customModels = models.filter(m => 'customKeyId' in m)
    const allCustomModelIds = new Set(customModels.map(model => model.id))
    const blockedCustomModelIds = allCustomModelIds.difference(allowedCustomModelIds)

    return isAllowlist || blockedDefaultModelKeys.size > 0 || blockedCustomModelIds.size > 0
  }, [allowedCustomModelIds, allowedModelKeys, isAllowlist, models])
  const [isAllSelected, setIsAllSelected] = useState(() => !anyRestrictions())

  const [isAllowAllModelsDialogOpen, setIsAllowAllModelsDialogOpen] = useState(false)

  const saveAllPublishersSelected = (newValue: string | null) => {
    if (newValue === 'all') {
      // Clear all rules
      if (anyRestrictions()) {
        setIsAllowAllModelsDialogOpen(true)
      } else {
        allowAllModels()
      }
    } else {
      setIsAllSelected(false)
    }
  }

  const allowAllModels = () => {
    setIsAllSelected(true)
    updateOrganizationAccessPolicy(allowAllOrgModelsPayload())
    setIsAllowAllModelsDialogOpen(false)
  }

  if (!isModelsEnabled) return null

  return (
    <>
      {isAllowAllModelsDialogOpen && (
        <ConfirmationDialog
          title="Allow all models"
          onClose={gesture => (gesture === 'confirm' ? allowAllModels() : setIsAllowAllModelsDialogOpen(false))}
          confirmButtonContent="Allow all models"
          confirmButtonType="primary"
        >
          <p>
            Are you sure you want to allow all models? This will delete any existing model restrictions for your
            organization.
          </p>
        </ConfirmationDialog>
      )}
      <RadioGroup onChange={saveAllPublishersSelected} name="models_restriction_setting">
        <RadioGroup.Label visuallyHidden>Select how models access should be restricted</RadioGroup.Label>
        <FormControl>
          <Radio value="all" checked={isAllSelected} />
          <FormControl.Label>All publishers</FormControl.Label>
          <FormControl.Caption>
            Enable current and future publishers available in the marketplace, as well as models added by custom keys.
            Processing of marketplace models is handled securely by GitHub and Azure and never shared with external
            model providers.
          </FormControl.Caption>
        </FormControl>
        <FormControl>
          <Radio value="models" checked={!isAllSelected} />
          <FormControl.Label>Only select models</FormControl.Label>
          <FormControl.Caption>Create an enabled or disabled list.</FormControl.Caption>
        </FormControl>
        {!isAllSelected && (
          <div className="d-block tmp-ml-4 tmp-my-3">
            <RulesTable
              orgDisplayLogin={orgDisplayLogin}
              customKeys={customKeys}
              models={models}
              publishers={publishers}
            />
          </div>
        )}
      </RadioGroup>
    </>
  )
}
