import {TrashIcon} from '@primer/octicons-react'
import {ActionList, Label, Spinner} from '@primer/react'
import {useOrganizationAccessPolicy} from '../contexts/OrganizationAccessPolicyContext'
import {allowOrgModelsPayload, restrictOrgModelsPayload} from '../hooks/use-update-organization-access-policy'
import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import {ProviderLogo} from '@github-ui/models-byok/providers/ProviderLogo'
import {orgSettingsByokCustomModelsPath} from '@github-ui/paths'

interface CustomModelRuleProps {
  customKey: CustomKey
  model: CustomModel
  orgDisplayLogin: string
}

export function CustomModelRule({customKey, model, orgDisplayLogin}: CustomModelRuleProps) {
  const {isAllowlist, isUpdatePending, pendingUpdateType, updateOrganizationAccessPolicy} =
    useOrganizationAccessPolicy()

  return (
    <ActionList.LinkItem className="py-2" href={orgSettingsByokCustomModelsPath({org: orgDisplayLogin})}>
      <ActionList.LeadingVisual>
        <ProviderLogo provider={customKey.provider} />
      </ActionList.LeadingVisual>
      <span>{model.name ?? model.slug}</span>
      {model.name !== undefined && model.name !== model.slug && (
        <span className="fgColor-muted">&nbsp;{model.slug}</span>
      )}
      <ActionList.Description>
        via {customKey.name}
        <Label className="ml-2">Custom</Label>
      </ActionList.Description>
      <ActionList.TrailingAction
        as="button"
        disabled={isUpdatePending}
        icon={() => {
          if (isUpdatePending && pendingUpdateType === 'rules') return <Spinner size="small" />
          return <TrashIcon />
        }}
        label={`Delete ${model.name ?? model.slug}`}
        onClick={() => {
          const payloadParams = {customModelIds: [model.id]}
          const payload = isAllowlist ? restrictOrgModelsPayload(payloadParams) : allowOrgModelsPayload(payloadParams)
          updateOrganizationAccessPolicy(payload)
        }}
      />
    </ActionList.LinkItem>
  )
}
