import {createContext, type PropsWithChildren, useCallback, use, useEffect, useMemo, useState} from 'react'
import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import type {DefaultModel, Publisher} from '../types'
import {useOrganizationAccessPolicy} from './OrganizationAccessPolicyContext'
import {usePublishers} from './PublishersContext'
import {getModelIdsByCustomKeyId} from '../utils/custom-keys'

interface SelectionContextType {
  selectedCustomModelIds: Set<number>
  selectedDefaultModelKeys: Set<string>
  partiallySelectedCustomKeyIds: Set<number>
  fullySelectedCustomKeyIds: Set<number>
  partiallySelectedPublisherIds: Set<number>
  fullySelectedPublisherIds: Set<number>
  deselectModels: (keysAndIdsToDeselect: Array<string | number> | Set<string | number>) => void
  selectModels: (keysAndIdsToSelect: Array<string | number> | Set<string | number>) => void
}

const SelectionContext = createContext<SelectionContextType | undefined>(undefined)

export function useSelection() {
  const context = use(SelectionContext)
  if (!context) throw new Error('useSelection must be used within a SelectionProvider')
  return context
}

export function SelectionProvider({
  children,
  customKeys,
  models,
  publishers,
}: PropsWithChildren<{
  customKeys: CustomKey[]
  models: Array<CustomModel | DefaultModel>
  publishers: Publisher[]
}>) {
  const customModels = useMemo(() => models.filter(model => 'customKeyId' in model), [models])
  const defaultModels = useMemo(() => models.filter(model => 'publisherId' in model), [models])
  const {allowedCustomModelIds, allowedModelKeys, isAllowlist} = useOrganizationAccessPolicy()
  const [selectedDefaultModelKeys, setSelectedDefaultModelKeys] = useState(() => {
    return isAllowlist
      ? allowedModelKeys
      : new Set(defaultModels.map(model => model.key).filter(key => !allowedModelKeys.has(key)))
  })
  const [selectedCustomModelIds, setSelectedCustomModelIds] = useState(() => {
    return isAllowlist
      ? allowedCustomModelIds
      : new Set(customModels.map(model => model.id).filter(id => !allowedCustomModelIds.has(id)))
  })
  const {modelKeysByPublisherId} = usePublishers()

  const customModelIdsByCustomKeyId = useMemo(
    () => getModelIdsByCustomKeyId({models: customModels, customKeys}),
    [customKeys, customModels],
  )
  const partiallySelectedPublisherIds = useMemo(() => {
    return new Set(
      publishers
        .map(publisher => publisher.id)
        .filter(publisherId => {
          const publisherModelKeys = modelKeysByPublisherId.get(publisherId) ?? new Set()
          const selectedPublisherModelKeys = selectedDefaultModelKeys.intersection(publisherModelKeys)
          return selectedPublisherModelKeys.size > 0
        }),
    )
  }, [modelKeysByPublisherId, publishers, selectedDefaultModelKeys])

  const partiallySelectedCustomKeyIds = useMemo(() => {
    return new Set(
      customKeys
        .map(customKey => customKey.id)
        .filter(customKeyId => {
          const customKeyModelIds = customModelIdsByCustomKeyId.get(customKeyId) ?? new Set()
          const selectedCustomKeyModelIds = selectedCustomModelIds.intersection(customKeyModelIds)
          return selectedCustomKeyModelIds.size > 0
        }),
    )
  }, [customKeys, customModelIdsByCustomKeyId, selectedCustomModelIds])
  const fullySelectedPublisherIds = useMemo(() => {
    return new Set(
      publishers
        .map(publisher => publisher.id)
        .filter(publisherId => {
          const publisherModelKeys = modelKeysByPublisherId.get(publisherId) ?? new Set()
          return publisherModelKeys.isSubsetOf(selectedDefaultModelKeys)
        }),
    )
  }, [modelKeysByPublisherId, publishers, selectedDefaultModelKeys])

  const fullySelectedCustomKeyIds = useMemo(() => {
    return new Set(
      customKeys
        .map(customKey => customKey.id)
        .filter(customKeyId => {
          const customKeyModelIds = customModelIdsByCustomKeyId.get(customKeyId) ?? new Set()
          return customKeyModelIds.isSubsetOf(selectedCustomModelIds)
        }),
    )
  }, [customKeys, customModelIdsByCustomKeyId, selectedCustomModelIds])

  const deselectModels = useCallback(
    (keysAndIdsToDeselect: Array<string | number> | Set<string | number>) => {
      const defaultModelKeysToDeselect = [...keysAndIdsToDeselect].filter(keyOrId => typeof keyOrId === 'string')
      setSelectedDefaultModelKeys(selectedDefaultModelKeys.difference(new Set(defaultModelKeysToDeselect)))

      const customModelIdsToDeselect = [...keysAndIdsToDeselect].filter(keyOrId => typeof keyOrId === 'number')
      setSelectedCustomModelIds(selectedCustomModelIds.difference(new Set(customModelIdsToDeselect)))
    },
    [selectedCustomModelIds, selectedDefaultModelKeys],
  )

  const selectModels = useCallback(
    (keysAndIdsToSelect: Array<string | number> | Set<string | number>) => {
      const defaultModelKeysToSelect = [...keysAndIdsToSelect].filter(keyOrId => typeof keyOrId === 'string')
      setSelectedDefaultModelKeys(new Set([...selectedDefaultModelKeys, ...defaultModelKeysToSelect]))

      const customModelIdsToSelect = [...keysAndIdsToSelect].filter(keyOrId => typeof keyOrId === 'number')
      setSelectedCustomModelIds(new Set([...selectedCustomModelIds, ...customModelIdsToSelect]))
    },
    [selectedCustomModelIds, selectedDefaultModelKeys],
  )

  const value = useMemo(
    () =>
      ({
        deselectModels,
        fullySelectedCustomKeyIds,
        fullySelectedPublisherIds,
        partiallySelectedCustomKeyIds,
        partiallySelectedPublisherIds,
        selectedCustomModelIds,
        selectedDefaultModelKeys,
        selectModels,
      }) satisfies SelectionContextType,
    [
      deselectModels,
      fullySelectedCustomKeyIds,
      fullySelectedPublisherIds,
      partiallySelectedCustomKeyIds,
      partiallySelectedPublisherIds,
      selectedCustomModelIds,
      selectedDefaultModelKeys,
      selectModels,
    ],
  )

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setSelectedDefaultModelKeys(
      isAllowlist
        ? allowedModelKeys
        : new Set(defaultModels.map(model => model.key).filter(key => !allowedModelKeys.has(key))),
    )
  }, [allowedModelKeys, isAllowlist, defaultModels])

  return <SelectionContext value={value}>{children}</SelectionContext>
}
