import {ActionList} from '@primer/react'
import type {Publisher} from '../types'
import type {CustomKey} from '@github-ui/models-byok/types'
import {useOrganizationAccessPolicy} from '../contexts/OrganizationAccessPolicyContext'
import {PublisherRule} from './PublisherRule'
import {usePublishers} from '../contexts/PublishersContext'
import {CustomKeyRule} from './CustomKeyRule'
import {RulesListBlankslate} from './RulesListBlankslate'

export function PublisherRulesList({
  allowedCustomKeyIds,
  blockedCustomKeyIds,
  customKeys,
  modelIdsByCustomKeyId,
  orgDisplayLogin,
  publishers,
}: {
  allowedCustomKeyIds: Set<number>
  blockedCustomKeyIds: Set<number>
  customKeys: CustomKey[]
  modelIdsByCustomKeyId: Map<number, Set<number>>
  orgDisplayLogin: string
  publishers: Publisher[]
}) {
  const {isAllowlist} = useOrganizationAccessPolicy()
  const {allowedPublisherIds, blockedPublisherIds} = usePublishers()
  const totalAllowingRules = allowedPublisherIds.size + allowedCustomKeyIds.size
  const totalBlockingRules = blockedPublisherIds.size + blockedCustomKeyIds.size

  if ((isAllowlist && totalAllowingRules < 1) || (!isAllowlist && totalBlockingRules < 1)) {
    return <RulesListBlankslate isAllowlist={isAllowlist} />
  }

  return (
    <ActionList className="Box-body px-0" aria-label="Publisher rules">
      {customKeys.map(customKey =>
        (isAllowlist && allowedCustomKeyIds.has(customKey.id)) ||
        (!isAllowlist && blockedCustomKeyIds.has(customKey.id)) ? (
          <CustomKeyRule
            customKey={customKey}
            key={`custom-key-${customKey.id}`}
            orgDisplayLogin={orgDisplayLogin}
            customModelIds={Array.from(modelIdsByCustomKeyId.get(customKey.id) ?? [])}
          />
        ) : null,
      )}
      {publishers.map(publisher =>
        (isAllowlist && allowedPublisherIds.has(publisher.id)) ||
        (!isAllowlist && blockedPublisherIds.has(publisher.id)) ? (
          <PublisherRule publisher={publisher} key={`publisher-${publisher.id}`} />
        ) : null,
      )}
    </ActionList>
  )
}
